import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Ce1WstT_.js";const m=JSON.parse('{"title":"5. Software Development Life Cycle (SDLC)","description":"","frontmatter":{},"headers":[],"relativePath":"development/sdlc.md","filePath":"development/sdlc.md"}'),l={name:"development/sdlc.md"};function s(o,e,r,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_5-software-development-life-cycle-sdlc" tabindex="-1">5. Software Development Life Cycle (SDLC) <a class="header-anchor" href="#_5-software-development-life-cycle-sdlc" aria-label="Permalink to &quot;5. Software Development Life Cycle (SDLC)&quot;">​</a></h1><p>The project followed a structured phased implementation approach:</p><h3 id="phase-1-planning" tabindex="-1">Phase 1: Planning <a class="header-anchor" href="#phase-1-planning" aria-label="Permalink to &quot;Phase 1: Planning&quot;">​</a></h3><ul><li>Defined the target audience (B2B wholesale) and operational workflows.</li><li>Evaluated technology stacks (React SPA vs Next.js SSR, Express vs NestJS).</li><li>Decided on React (Vite) + Express + Supabase PostgreSQL for maximum velocity and free-tier compatibility.</li></ul><h3 id="phase-2-requirement-analysis" tabindex="-1">Phase 2: Requirement Analysis <a class="header-anchor" href="#phase-2-requirement-analysis" aria-label="Permalink to &quot;Phase 2: Requirement Analysis&quot;">​</a></h3><ul><li>Conducted deep research into required DB schemas and normalization.</li><li>Defined the strict RBAC matrix for Admin, Sales, Warehouse, and Accounts.</li><li>Outlined concurrency requirements for inventory deductions.</li></ul><h3 id="phase-3-system-design" tabindex="-1">Phase 3: System Design <a class="header-anchor" href="#phase-3-system-design" aria-label="Permalink to &quot;Phase 3: System Design&quot;">​</a></h3><ul><li>Drafted the 3NF database schema (Users, Customers, Products, Challans, etc.).</li><li>Outlined API routes and standard JSON response payloads.</li><li>Designed the transactional strategy using <code>SELECT FOR NO KEY UPDATE</code>.</li></ul><h3 id="phase-4-implementation" tabindex="-1">Phase 4: Implementation <a class="header-anchor" href="#phase-4-implementation" aria-label="Permalink to &quot;Phase 4: Implementation&quot;">​</a></h3><ul><li>Separated the workspace into <code>client/</code> and <code>server/</code> mono-repo structure.</li><li>Developed backend routes, Zod validation, and pg-based repositories.</li><li>Developed frontend components, API service connectors, and TanStack Query hooks.</li><li>Implemented the UI utilizing Tailwind CSS.</li></ul><h3 id="phase-5-testing" tabindex="-1">Phase 5: Testing <a class="header-anchor" href="#phase-5-testing" aria-label="Permalink to &quot;Phase 5: Testing&quot;">​</a></h3><ul><li>Executed unit tests on API logic and Zod validators.</li><li>Executed integration testing on the backend RBAC mechanisms.</li><li>Conducted critical concurrency simulations to verify the database lock mechanic successfully blocks negative stock.</li></ul><h3 id="phase-6-deployment" tabindex="-1">Phase 6: Deployment <a class="header-anchor" href="#phase-6-deployment" aria-label="Permalink to &quot;Phase 6: Deployment&quot;">​</a></h3><ul><li>Containerized the backend using Docker (<code>docker-compose.yml</code>) for local testing.</li><li>Prepared Vite environment variables for Vercel deployment.</li><li>Configured Express to serve via Render/Railway on <code>env.PORT</code>.</li></ul><h3 id="phase-7-maintenance-future-improvements" tabindex="-1">Phase 7: Maintenance / Future Improvements <a class="header-anchor" href="#phase-7-maintenance-future-improvements" aria-label="Permalink to &quot;Phase 7: Maintenance / Future Improvements&quot;">​</a></h3><ul><li>Identified areas for future expansion (e.g., multi-warehouse tables, billing flows, frontend E2E tests).</li></ul>',16)])])}const p=a(l,[["render",s]]);export{m as __pageData,p as default};
